","import React, { useState, useCallback } from "react";
import { RecordProvider } from "@servicenow/react-components/RecordContext";
import { useRecord } from "@servicenow/react-components";
import { FormActionBar } from "@servicenow/react-components/FormActionBar";
import { FormColumnLayout } from "@servicenow/react-components/FormColumnLayout";
import { Button } from "@servicenow/react-components/Button";
import { Modal } from "@servicenow/react-components/Modal";

interface UrlCreateProps {
 table: string;
 sysId?: string;
 onBack: () => void;
}

function FormContent({ onBack }: { onBack: () => void }) {
 const { form } = useRecord();
 const [showModal, setShowModal] = useState(false);

 const handleBack = useCallback(() => {
 if (form.isDirty) {
 setShowModal(true);
 } else {
 onBack();
 }
 }, [form.isDirty, onBack]);

 return (
 <div className="create-form-wrapper">
 <div className="create-form-header">
 <Button
 label="Back to List"
 variant="secondary"
 icon="arrow-left-fill"
 onClicked={handleBack}
 />
 </div>
 <FormActionBar />
 <FormColumnLayout />
 <Modal
 opened={showModal}
 size="sm"
 headerLabel="Unsaved Changes"
 content="You have unsaved changes. Are you sure you want to leave?"
 footerActions={[
 { label: "Stay", variant: "secondary" },
 { label: "Leave", variant: "primary-negative" },
 ]}
 onOpenedSet={() => setShowModal(false)}
 onFooterActionClicked={(e: any) => {
 const action = e.detail.payload.action;
 if (action.label === "Leave") {
 setShowModal(false);
 onBack();
 } else {
 setShowModal(false);
 }
 }}
 />
 </div>
 );
}

export default function UrlCreate({ table, sysId, onBack }: UrlCreateProps) {
 return (
 <div className="view-container">
 <RecordProvider
 table={table}
 sysId={sysId || "-1"}
 isReadOnly={false}
 >
 <FormContent onBack={onBack} />
 </RecordProvider>
 </div>
 );
}
