 setCurrentView({ view: viewName, recordId: recordId || null });
 },
 []
 );

 const { view, recordId } = currentView;

 return (
 <div className="app-container">
 {view === "list" && (
 <UrlList
 table={TABLE}
 onRowClicked={(sysId: string) =>
 navigateToView("detail", sysId, {
 title: "Accessibility Test Detail",
 })
 }
 onNewClicked={() =>
 navigateToView("create", null, {
 title: "Submit New URL",
 })
 }
 />
 )}

 {view === "create" && (
 <UrlCreate
 table={TABLE}
 onBack={() =>
 navigateToView("list", null, {
 title: "Accessibility Tests",
 })
 }
 />
 )}

 {view === "detail" && recordId && (
 <UrlCreate
 table={TABLE}
 sysId={recordId}
 onBack={() =>
 navigateToView("list", null, {
 title: "Accessibility Tests",
 })
 }
 />
 )}
 </div>
 );
}
